        statement.execute("PRAGMA synchronous=FULL");
        statement.execute("PRAGMA busy_timeout=5000");
    }
} catch (io.github.diodeme.ji.storage.sqlite.SqliteMigrationException exception) {
    throw storage("cannot open SQLite Session repository",
            new SQLException("SQLite Session schema is obsolete; restore a pre-migration backup", exception));
} catch (SQLException exception) {
    throw storage("cannot open SQLite Session repository", exception);
}
